#include <cassert>
#include "phase4_live_test_support.hpp"
int main(){using namespace phase4_live_test;auto e=environment("task-f7l-workflow");auto m=matrix(e);DeterministicExecutor executor;InMemoryRoleCertificationStore store;RoleLiveCertificationWorkflow workflow(store,executor);auto r=workflow.run(e,m,options());assert(r.state==RoleCertificationState::Certified);assert(r.report&&r.report->executed&&r.report->blockers.empty());assert(r.report->cells.size()==m.cells.size());assert(role_certification_valid_for(*r.report,e,m,"2026-08-11T00:00:00Z",verify));auto replay=workflow.run(e,m,options());assert(replay.state==RoleCertificationState::Certified&&replay.report);auto revised=e;revised.git_revision="git:different";auto blocked=workflow.run(revised,m,options());assert(blocked.state==RoleCertificationState::Failed&&blocked.error_code=="contract_invalid");InMemoryRoleCertificationStore approval_store;RoleLiveCertificationWorkflow approval_workflow(approval_store,executor);auto pending_options=options("approval-resume");pending_options.approval_decision_id.clear();pending_options.approval_validator={};auto pending=approval_workflow.run(e,m,pending_options);assert(pending.state==RoleCertificationState::AwaitingApproval&&!approval_store.load_report("tenant-live","approval-resume"));auto approved=approval_workflow.run(e,m,options("approval-resume"));assert(approved.state==RoleCertificationState::Certified&&approval_store.load_report("tenant-live","approval-resume"));return 0;}
